import { HttpErrorResponse } from '@angular/common/http';
import { FieldTree, ValidationError } from '@angular/forms/signals';

export interface ProblemDetail {
  status: number;
  title: string;
  detail?: string;
  errors?: ProblemFieldError[];
}

export interface ProblemFieldError {
  field: string | null;
  message: string;
}

export function problemDetailMessage(error: unknown): string {
  if (error instanceof HttpErrorResponse) {
    const problem = error.error as ProblemDetail | null;
    return problem?.detail ?? problem?.title ?? error.message;
  }
  return 'Unexpected error';
}

export function loadErrorMessage(error: unknown, notFoundMessage: string): string {
  if (error instanceof HttpErrorResponse && error.status === 404) {
    return notFoundMessage;
  }
  return problemDetailMessage(error);
}

export function problemDetailToFormErrors<T extends object>(
  error: unknown,
  form: FieldTree<T>,
): ValidationError.WithOptionalFieldTree[] {
  const fieldErrors =
    error instanceof HttpErrorResponse ? (error.error as ProblemDetail | null)?.errors : undefined;
  if (!fieldErrors?.length) {
    // A 409 conflict carries no field errors: it is an error of the whole form, not of a field.
    return [{ kind: 'server', message: problemDetailMessage(error), fieldTree: form }];
  }
  const fields = form as unknown as Record<string, FieldTree<unknown> | undefined>;
  return fieldErrors.map(({ field, message }) => ({
    kind: 'server',
    message,
    fieldTree: (field === null ? undefined : fields[field]) ?? form,
  }));
}
import { numberAttribute } from '@angular/core';

export function optionalNumberAttribute(value: string | undefined): number | undefined {
  return value === undefined ? undefined : numberAttribute(value);
}
import { provideHttpClient } from '@angular/common/http';
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideRouter, withComponentInputBinding } from '@angular/router';
import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(),
    provideRouter(routes, withComponentInputBinding()),
  ],
};
.
